import{_ as i,o as t,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Crimson Project Updates | Ceph Days London 2024","description":"","frontmatter":{"title":"Crimson Project Updates | Ceph Days London 2024","date":"2024-08-23T00:00:00.000Z","updated":"2024-08-24T00:00:00.000Z","tags":["[Ceph]","[Crimson 项目]","[分布式存储]","[性能优化]","[异步编程]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Crimson_Project_Updates_Ceph_Days_London_2024.md","filePath":"posts/2024/Crimson_Project_Updates_Ceph_Days_London_2024.md","lastUpdated":1780459816000}'),s={name:"posts/2024/Crimson_Project_Updates_Ceph_Days_London_2024.md"};function n(e,o,p,a,_,C){return t(),l("div",null,[...o[0]||(o[0]=[r("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Matan（Crimson项目负责人）、其他Crimson项目成员</p><p><strong>会议主题</strong>： Crimson项目概述及最新进展</p><p><strong>会议内容</strong>：</p><p><strong>一、Crimson项目背景</strong></p><ul><li>随着存储技术的发展，从硬盘到NVMe，存储速度和吞吐量显著提升，对CPU效率提出了更高要求。</li><li>传统Ceph架构在处理高吞吐量存储设备时，存在CPU开销大的问题，Crimson项目旨在优化此问题。</li></ul><p><strong>二、Crimson项目核心思想</strong></p><ul><li>采用异步编程模型，避免线程切换带来的开销。</li><li>使用Sear框架实现异步编程，提高CPU效率。</li><li>采用单线程每核心架构，避免线程间的竞争和同步开销。</li></ul><p><strong>三、Crimson项目架构</strong></p><ul><li>Crimson项目是Ceph OSD的完全重写，采用Sear框架实现异步编程。</li><li>项目包括以下组件： <ul><li>OSD：负责IO处理，使用Sear框架进行异步编程。</li><li>对象存储：负责数据存储，支持BlueStore和CStore两种后端。</li><li>CStore：Crimson项目自研对象存储后端，使用Sear框架实现，支持NVMe等新型存储设备。</li></ul></li></ul><p><strong>四、Crimson项目进展</strong></p><ul><li>最新版本已进入技术评审阶段，支持RBD工作负载在副本池中运行。</li><li>支持多核CPU，提高性能。</li><li>支持BlueStore和CStore两种对象存储后端。</li><li>支持快速部署，自动识别可用CPU资源。</li><li>支持垃圾回收和快照功能。</li><li>支持RBD快照复制功能。</li><li>支持数据恢复和备份功能。</li><li>测试覆盖率持续提升，包括OSD测试、垃圾回收测试和快照测试。</li></ul><p><strong>五、Crimson项目未来计划</strong></p><ul><li>扩大测试覆盖率，包括PG拆分/合并、RBD快照复制等功能。</li><li>优化性能，特别是CStore后端性能。</li><li>支持动态分片，提高资源利用率。</li><li>支持异构存储配置。</li></ul><p><strong>六、讨论</strong></p><ul><li>项目成员讨论了CStore后端性能优化、测试覆盖率提升等问题。</li><li>Matan强调了Crimson项目的技术预览性质，提醒用户谨慎使用。</li></ul><p><strong>七、行动计划</strong></p><ul><li>继续进行技术预览版本的开发和测试。</li><li>优化CStore后端性能。</li><li>扩大测试覆盖率。</li><li>完善文档和开发指南。</li></ul><p><strong>八、总结</strong></p><p>Crimson项目是Ceph架构的重要改进，旨在提高CPU效率，更好地利用新型存储设备。项目进展顺利，未来将继续优化性能，扩大功能覆盖范围。</p>",22)])])}const m=i(s,[["render",n]]);export{d as __pageData,m as default};
